import numpy as np


def _affine(x):
    return np.column_stack((np.ones(len(x)), x))


def _readout(c):
    return np.column_stack((_affine(c), np.sum(c[:, :2] * c[:, 2:], axis=1)))


def run_node(inputs: dict) -> dict:
    study = inputs['__input__']
    coords = inputs['node_00']
    train = study['train']
    c, query = coords['c'], coords['query']
    readout_beta = np.linalg.lstsq(_readout(c), np.asarray(train['y'], dtype=float), rcond=None)[0]
    y_hat = _readout(query) @ readout_beta
    design, new_design = _affine(c), _affine(query)
    beta = np.linalg.lstsq(design, np.asarray(train['traj'], dtype=float), rcond=None)[0]
    fitted = design @ beta
    times = np.asarray(study['eval_times'], dtype=float)
    scale = max(float(np.max(np.abs(times))), np.finfo(float).tiny)
    return {'y_hat': y_hat, 'beta': beta, 'fitted': fitted,
            'new_design': new_design, 't': times / scale}

